		LOGGER.info("unAssigning Transaction on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Transaction on the parent entithy
		// ------------------------------------------     
	    parentEntity.setTransaction(null);

	    // ------------------------------------------
